mapper.select:
SELECT STATUS, STATUS_CD, TEST_TYPE_CD as DOCUMENT_TYPE, SUM(cap_dist_cnt) as CAPITAL_DISTRICT, SUM (syr_cnt) as SYRACUSE, SUM (new_roch_cnt) as NEW_ROCHELLE, SUM (long_is_cnt) as LONG_ISLAND, SUM (roch_cnt) as ROCHESTER, SUM( buff_cnt) as BUFFALO, SUM (nyc_cnt ) as NEW_YORK_CITY, SUM (co_cnt) as CENTRAL_OFFICE, SUM(cap_dist_cnt)+ SUM (syr_cnt) + SUM (new_roch_cnt) + SUM (long_is_cnt) + SUM (roch_cnt) + SUM( buff_cnt) + SUM (nyc_cnt )+ SUM ( co_cnt) TOTAL, (case status when 'Open' then 1 when 'Reopened' then 2 when 'Needs assignment' then 3 when 'Reassignment requested' then 4 when 'Pending ACRF review' then 5 when 'Rejected' then 6 else 7 end) as sort_order FROM (select /*+ INDEX(D,DOCUMENT_LOCATOR_PK)*/ CASE WHEN b.CURRENT_ASSIGNMENT_STATUS NOT IN ('CLOSED','CLS_ADM') THEN s.status_description ELSE s.activity_type_description END STATUS, CASE WHEN b.CURRENT_ASSIGNMENT_STATUS NOT IN ('CLOSED','CLS_ADM') THEN b.CURRENT_ASSIGNMENT_STATUS ELSE s.ACTIVITY_TYPE_CODE END STATUS_CD, (case when b.current_region_cd = '1' then 1 else 0 end) as cap_dist_cnt, (case when b.current_region_cd = '2' then 1 else 0 end) as syr_cnt, (case when b.current_region_cd = '3' then 1 else 0 end) as new_roch_cnt, (case when b.current_region_cd = '4' then 1 else 0 end) as long_is_cnt, (case when b.current_region_cd = '5' then 1 else 0 end) as roch_cnt, (case when b.current_region_cd = '6' then 1 else 0 end) as buff_cnt, (case when b.current_region_cd = '7' then 1 else 0 end) as nyc_cnt, (case when b.current_region_cd = '9' then 1 else 0 end) as co_cnt, D.TEST_TYPE_CD from surveillance_assignment b, coded_assignment_status s, coded_activity_type s , DOCUMENT_LOCATOR D where b.CREATE_DATE BETWEEN TO_DATE(#{fromDate},'MM/DD/YYYY') AND TO_DATE(#{toDate},'MM/DD/YYYY') + 1 and b.current_assignment_status = s.status_cd AND d.document_type_code ='HIV_LAB'
AND d.TEST_TYPE_CD = #{testType}
AND b.triggering_doc_id = d.DOCUMENT_ID and b.current_activity_type_code = s.activity_type_code (+) ) GROUP BY status,status_CD,TEST_TYPE_CD UNION select 'TOTALS' as status,null,null,null,null,null,null,null,null,null,null,null,10 as sort_order from dual order by sort_order, status,DOCUMENT_TYPE

select s.STATENO, region.REGION_DESCRIPTION CATEGORY_DESCRIPTION, CASE WHEN s.CURRENT_ASSIGNMENT_STATUS NOT IN ('CLOSED','CLS_ADM') THEN coded_assignment_status.status_description ELSE coded_activity_type.activity_type_description END ASSIGNMENT_STATUS, PKG_TRK_COMMON.fn_get_fullname(U.LAST_NAME ,U.FIRST_NAME ,U.MIDDLE_NAME , NULL) WORKER_NAME from SURVEILLANCE_ASSIGNMENT s , WORKER_ASSIGNMENT W , USER_REGION R , NYEHMS_USERS U , CODED_REGION region, coded_assignment_status coded_assignment_status, coded_activity_type coded_activity_type,
DOCUMENT_LOCATOR D
where s.triggering_doc_id = d.DOCUMENT_ID
and D.DOCUMENT_TYPE_CODE = #{documentType}
AND D.TEST_TYPE_CD = #{testType}
and D.TEST_TYPE_CD = #{documentType}
and s.CREATE_DATE between TO_DATE(#{fromDate},'MM/DD/YYYY') and TO_DATE(#{toDate},'MM/DD/YYYY') +1
${stdTableName} std WHERE TRIGGERING_DOC_ID = std.document_id
and std.${FileNameReferenceColumn} = #{fileName}
and s.CREATE_DATE between TO_DATE(#{fromDate},'MM/DD/YYYY') and TO_DATE(#{toDate},'MM/DD/YYYY')+1
and CURRENT_ASSIGNMENT_STATUS in ('CLOSED', 'CLS_ADM')
and CURRENT_ASSIGNMENT_STATUS = UPPER(#{assignmentStatus})
AND CASE WHEN #{activityTypeCode} IS NULL THEN '1' ELSE #{activityTypeCode} END = CASE WHEN #{activityTypeCode} IS NULL THEN '1' ELSE S.CURRENT_ACTIVITY_TYPE_CODE END
and CURRENT_REGION_CD = #{regionId}
and s.current_assignment_status = coded_assignment_status.status_cd(+) and s.CURRENT_REGION_CD = region.REGION_CODE(+) and s.current_activity_type_code = coded_activity_type.activity_type_code (+) AND s.CURRENT_WORKER_ASSIGNMENT_ID = W.WORKER_ASSIGNMENT_ID(+) AND W.WORKER_REGION_ID = R.WORKER_REGION_ID (+) AND R.WORKER_ID = U.WORKER_ID(+) order by REGION_DESCRIPTION, CURRENT_ASSIGNMENT_STATUS, WORKER_NAME asc

select surv.STATENO, surv.AHI_UPDATE_DATE, surv.AHI_UPDATE_UID from SURVEILLANCE_ASSIGNMENT surv, document_locator doc where surv.TRIGGERING_DOC_ID = doc.document_id and (doc.document_Type_code =#{documentType} or doc.test_Type_Cd = #{documentType}) and surv.current_Region_cd = #{regionId} and (surv.CURRENT_ASSIGNMENT_STATUS = #{assignmentStatus} or surv.CURRENT_ACTIVITY_TYPE_CODE = #{assignmentStatus})
and AHI_FLAG = 'Y' and surv.create_date > sysdate-90
and AHI_FLAG = #{ahiFlag}
